import assert from 'node:assert/strict';
import { createCanvasKernel, nodeId } from '@nodebraid/kernel';
import { acceptInteractionProjection } from './packages/renderer-svg/src/interaction-projection.ts';
const kernel = createCanvasKernel(), a = nodeId('a'), b = nodeId('b');
kernel.transact(tx => {
  tx.nodes.add({ id:a, type:'task', position:{x:10,y:20}, size:{width:20,height:20}, data:null });
  tx.nodes.add({ id:b, type:'task', position:{x:100,y:110}, size:{width:20,height:20}, data:null });
});
const view = kernel.read();
const ports = Object.freeze({ documentRevision:view.snapshot.revision, generation:0, nodes:Object.freeze([]) });
const session = Object.freeze({ selection:Object.freeze({ nodeIds:Object.freeze([]), edgeIds:Object.freeze([]) }), viewport:Object.freeze({x:0,y:0,zoom:1}) });
const candidates = [
  Object.freeze({nodeId:a,basePosition:view.query.getNode(a).position,position:Object.freeze({x:30,y:40})}),
  Object.freeze({nodeId:b,basePosition:view.query.getNode(b).position,position:Object.freeze({x:150,y:160})}),
];
const expected = candidates.map(c => ({id:c.nodeId,base:c.basePosition,position:c.position}));
const observe = (nodes) => acceptInteractionProjection({type:'node-drag',nodes},view.snapshot,ports,session).nodes.map(c => ({id:c.nodeId,base:c.basePosition,position:c.position}));
const ordinary = observe(Object.freeze([...candidates])); assert.deepEqual(ordinary,expected);
const custom = [...candidates]; let mapCalls = 0;
Object.defineProperty(custom,'map',{value:function(callback,thisArg){
  mapCalls++;
  return Array.prototype.map.call(this,(candidate,index,array)=>callback.call(thisArg,candidate,1-index,array));
}});
Object.freeze(custom);
const actual = observe(custom);
assert.deepEqual(actual.map(row=>row.id),[a,b]);
assert.equal(mapCalls,1); assert.equal(kernel.read(),view);
console.log(JSON.stringify({ordinaryControl:ordinary,expected,actual,canonicalIds:true,mapCalls,unchangedKernel:true,scope:'pure acceptor/internal boundary; not public Renderer or DOM/browser proof'}));
assert.deepEqual(actual,expected,'Accepted per-ID geometry must not depend on caller map callback index');

